Section Tail.
  Context {fx : OSSVerify.Proofs.boost_json.fuzz_parse.lib.PropExec.FPState}.
  Variable sp0 : word.
  Variable BL : ltac2:(zQ "30!h8!j7!q0@1$0@1$0@1$2@1$1#8").          (* [comment removed for export] *)
  Variable model : ltac2:(zQ "10!ms7$0").
  Hypothesis Hvsp : ltac2:(zQ "10!mt0@1$0?3sp0").
  Hypothesis Hh : ltac2:(zQ "60!j7!q0!lt8!hv8!hp1!mtc@3$4@1$3@1$1@1$0#k0@1$5?5model@1$2@1$1@1$0#k0").
  Hypothesis Hlazy : ltac2:(zQ "71!j7!q0!mu8!h8!lo9!hp1!mue&@2$2@1$1@1$0#k0@1$1@1$0#k0@3$5@1$3~0@1$6?5model@1$4~0").
  Hypothesis Hfd2 : ltac2:(zQ "90!j7!mvb!kn8!ljf!hv8!hp1!ng6!nh3!ni0@3$5@1$4$1@2$7@1$8?5model@2$2@1$0#k0+2@2$3$1@1$6@2$2@1$0#k0+2").
  (* LPS 75d69e00: the stderr write and the exit flush need the launch's channel
     reader (stdio_call_sound / ref_exit_Z premise), constant over the run. *)
  Hypothesis Hrdr : m_channel_reader model = true.

  Definition ENV : ltac2:(zQ "40!h8!j7!nd!q0>4vals@1$0@1$3@1$1#k0$2") := ltac2:(zQ "60!h8!j7!u0!ub!hia!q0\4vals@1$0@1$5@1$1#k0@2$3@1$4^1@1$2?2BL").

  Let SPlo : (0x7fff80000000 <= bv_unsigned sp0)%Z := proj1 Hvsp.
  Let SPhi : (bv_unsigned sp0 <= 0x800000000000)%Z := proj1 (proj2 Hvsp).

