  Lemma of_segI : ltac2:(zQ "h80!j7!q0!hma!hp1!hu4!hub!h8!hv3!hv8!iic!im3!ip1!it5!itd!jhf!jmb!jn7!jr8!kga!kh5!hia!km8!kn0!kn8>4vals@1$6@1$1@1$0#k0>1R@2$b@1$0#5@1$1@1$0#k0>1M>0@1$1@1$0#k0@1$8@1$1@1$0#8>0@3$3$7@2$5@1$1@1$0#k0^3Nhg7>0@3$3@1$1@1$0#k0@2$h4^4N0?3sp0>0@3$h3@1$4^5$h6^4>0@4$h2$2@1$4^6^4$h5@4$f$2$e@2$9@5$c?2fx^6@2$h7@1$0#k0+ujrp4^5@1$d$2?5model@2$h0@1$h1+2@1$a?5model").
Proof.
    (* LPS 75d69e00: replay replaced (it applied ref_exit_Z at the old arity). Shape from
       boost-beast http_request RefOpenFailCS_tail.v of_segI; boost-json's tp is 0x10ebf8
       (tid cell 0x10eb50) and its exit_common fixes the atexit head word (axh = 0). *)
    intros vals R M HL P0 HR HK.
    pose proof SPlo as Hlo. pose proof SPhi as Hhi.
    run_blk scr0 263%nat.
    apply (rz_conseq RSEGS _ (t_emit (W 1 []) (t_exit (bv_and (Z_to_bv 64 2) (Z_to_bv 64 255)) (m_fs model)))).
    2:{ cbn [W map].
        replace (bv_and (Z_to_bv 64 2) (Z_to_bv 64 255)) with (exit_code 2) by (apply bv_eq; reflexivity).
        apply t_eq_sym. apply t_emit_nil_exit. }
    apply ref_exit_Z; [|exact Hrdr].
    pose proof (know_nth RSEGS _ _ knI ltac:(let i := kidx knI (is_krange (EVar 5)) in exact i) _ HK eq_refl)
      as Ktid; cbn [kentry_ok edenot ev ENV] in Ktid.
    exists (Z_to_bv 64 (bv_unsigned sp0 - 128)), (Z_to_bv 64 0x10ebf8), (bv_unsigned (vals_ev vals 5)),
           (Z_to_bv 64 0), (Z_to_bv 64 0).
    split; [|split; [exact Hh|split; [exact Hlazy|]]].
    + constructor.
      * regv HR (2 : reg). rewrite edenot_add_lit. unfold adenot, v_addi. cbn [a_base a_off edenot ev ENV].
        rewrite P0. f_equal; lia.
      * regv HR (4 : reg). reflexivity.
      * regv HR (10 : reg). reflexivity.
      * rewrite u_small by lia. lia.
      * rewrite u_small by lia. lia.
      * rewrite u_small by lia.
        pose proof (kwr_store_ok RSEGS (ENV vals) _ knI ltac:(let i := kidx knI (is_kwr_cov (EVar 0) (-272) 144) in exact i)
                      _ _ _ (-272) 144 HK eq_refl ltac:(lia) ltac:(cbn; lia)) as Hst.
        unfold adenot, v_addi in Hst. cbn [a_base a_off edenot ev ENV] in Hst. rewrite P0 in Hst.
        replace (bv_unsigned sp0 - 128 - 144)%Z with (bv_unsigned sp0 + -272)%Z by lia. exact Hst.
      * lit_u. lia.
      * lit_u. lia.
      * lia.
      * lit_u. change (1108984 - 168)%Z with 0x10eb50%Z.
        krd HK 0x10eb50%Z 4%nat Htc. rewrite Htc. cbn [ev ENV].
        rewrite ext_val_zx_id by (change (2 ^ (8 * Z.of_nat 4))%Z with 4294967296%Z; lia).
        rewrite Z_to_bv_bv_unsigned. reflexivity.
      * krd_solve HK.
      * krd_solve HK.
      * krd_solve HK.
      * krd_solve HK.
      * krd_solve HK.
      * krd_solve HK.
      * krd_solve HK.
      * krd_solve HK.
      * krd_solve HK.
      * krd_solve HK.
      * repeat split; krd_solve HK.
      * repeat split; krd_solve HK.
    + left. split; [reflexivity|].
      exists (Z_to_bv 64 0), (Z_to_bv 64 0). repeat split; krd_solve HK.
Qed.

